import React, { useState } from 'react';
import {
  Card,
  CardContent,
  CardActions,
  Typography,
  TextField,
  IconButton,
  Box,
  Paper,
  Chip,
  Rating
} from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import AccessTimeIcon from '@mui/icons-material/AccessTime';
import RestaurantIcon from '@mui/icons-material/Restaurant';
import { Recipe } from '../types/Recipe';
import MuscleRating from './MuscleRating';

interface MealCardProps {
  meal: Recipe;
  onSelect: () => void;
  onUpdateServings: (servings: number) => void;
  onUpdateRating: (rating: number) => void;
}

const MealCard: React.FC<MealCardProps> = ({
  meal,
  onSelect,
  onUpdateServings,
  onUpdateRating
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [servings, setServings] = useState(meal.servings);

  const handleServingsChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const newServings = parseInt(event.target.value) || 1;
    setServings(newServings);
    onUpdateServings(newServings);
  };

  return (
    <Card 
      sx={{ 
        height: '100%', 
        display: 'flex', 
        flexDirection: 'column',
        cursor: 'pointer',
        transition: 'transform 0.2s, box-shadow 0.2s',
        '&:hover': {
          transform: 'translateY(-4px)',
          boxShadow: 6,
        },
      }}
      onClick={onSelect}
    >
      <CardContent sx={{ flexGrow: 1 }}>
        <Typography variant="h6" component="h2" gutterBottom>
          {meal.name}
        </Typography>
        <Typography variant="body2" color="text.secondary" paragraph>
          {meal.description}
        </Typography>
        
        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 2 }}>
          <Chip
            icon={<AccessTimeIcon />}
            label={`${meal.prepTime + meal.cookTime} min`}
            size="small"
            color="primary"
            variant="outlined"
          />
          <Chip
            icon={<RestaurantIcon />}
            label={`${meal.servings} porties`}
            size="small"
            color="secondary"
            variant="outlined"
          />
        </Box>

        <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
          <Typography variant="body2" sx={{ mr: 1 }}>
            Bereidingstijd: {meal.prepTime + meal.cookTime} min
          </Typography>
          <IconButton size="small" onClick={() => setIsEditing(!isEditing)}>
            <EditIcon />
          </IconButton>
        </Box>

        {isEditing && (
          <TextField
            label="Aantal personen"
            type="number"
            value={servings}
            onChange={handleServingsChange}
            size="small"
            fullWidth
            sx={{ mb: 1 }}
          />
        )}

        <Box sx={{ display: 'flex', alignItems: 'center' }}>
          <Typography variant="body2" sx={{ mr: 1 }}>
            Beoordeling:
          </Typography>
          <MuscleRating
            value={meal.rating}
            onChange={(_, newValue) => onUpdateRating(newValue || 0)}
          />
        </Box>
      </CardContent>
      <CardActions>
        <Typography variant="body2" color="text.secondary">
          {meal.ingredients.length} ingrediënten
        </Typography>
      </CardActions>
    </Card>
  );
};

export default MealCard; 