import React, { useState } from 'react';
import {
  Box,
  Typography,
  Grid,
  Card,
  CardContent,
  CardActions,
  Button,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  List,
  ListItem,
  ListItemText,
  Stack,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  ListItemSecondaryAction,
  useMediaQuery,
  useTheme,
  ListItemButton,
  Divider,
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import EditIcon from '@mui/icons-material/Edit';
import ShoppingCartIcon from '@mui/icons-material/ShoppingCart';
import DeleteIcon from '@mui/icons-material/Delete';
import { Recipe, MealPlan } from '../types/Recipe';
import ShoppingList from './ShoppingList';
import MuscleRating from './MuscleRating';
import { predefinedMeals } from '../data/meals';
import { Ingredient } from '../types/Recipe';
import MealCard from './MealCard';

interface MealPlannerProps {
  mealPlan: MealPlan;
  onAddMeal: (meal: Recipe, servings: number) => void;
  onUpdateServings: (mealId: string, servings: number) => void;
  onUpdateRating: (mealId: string, rating: number) => void;
  selectedMeal: Recipe | null;
  onSelectMeal: (meal: Recipe | null) => void;
  onShoppingListUpdate: (ingredients: { name: string; amount: number; unit: string }[]) => void;
}

const MealPlanner: React.FC<MealPlannerProps> = ({
  mealPlan,
  onAddMeal,
  onUpdateServings,
  onUpdateRating,
  selectedMeal,
  onSelectMeal,
  onShoppingListUpdate,
}) => {
  const [isAddMealOpen, setIsAddMealOpen] = useState(false);
  const [isShoppingListOpen, setIsShoppingListOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [newServings, setNewServings] = useState<number>(1);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const categories = {
    'all': 'Alle maaltijden',
    'breakfast': 'Ontbijt',
    'lunch': 'Lunch',
    'dinner': 'Avondmaaltijd',
    'snack': 'Snacks'
  };

  const getMealCategory = (mealId: string): string => {
    const id = parseInt(mealId);
    if (id >= 100 && id < 200) return 'breakfast';
    if (id >= 200 && id < 300) return 'lunch';
    if (id >= 300 && id < 400) return 'snack';
    return 'dinner';
  };

  const filteredMeals = selectedCategory === 'all'
    ? predefinedMeals
    : predefinedMeals.filter(meal => getMealCategory(meal.id) === selectedCategory);

  const handleAddMeal = (meal: Recipe) => {
    onAddMeal(meal, newServings);
    setIsAddMealOpen(false);
    setNewServings(1);
  };

  const handleGenerateShoppingList = () => {
    const allIngredients = mealPlan.meals.flatMap(meal => 
      meal.ingredients.map(ingredient => ({
        ...ingredient,
        amount: ingredient.amount * meal.servings
      }))
    );
    onShoppingListUpdate(allIngredients);
    setIsShoppingListOpen(true);
  };

  return (
    <Box sx={{ p: 2 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h4">Maaltijdplan</Typography>
        <Stack direction="row" spacing={2}>
          <Button
            variant="contained"
            startIcon={<ShoppingCartIcon />}
            onClick={handleGenerateShoppingList}
          >
            Boodschappenlijst
          </Button>
          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => setIsAddMealOpen(true)}
          >
            Maaltijd toevoegen
          </Button>
        </Stack>
      </Box>

      <FormControl sx={{ mb: 3, minWidth: 200 }}>
        <InputLabel>Categorie</InputLabel>
        <Select
          value={selectedCategory}
          label="Categorie"
          onChange={(e) => setSelectedCategory(e.target.value)}
        >
          {Object.entries(categories).map(([key, value]) => (
            <MenuItem key={key} value={key}>{value}</MenuItem>
          ))}
        </Select>
      </FormControl>

      <Grid container spacing={2}>
        {mealPlan.meals.map((meal) => (
          <Grid item xs={12} sm={6} md={4} key={meal.id}>
            <MealCard
              meal={meal}
              onSelect={() => onSelectMeal(meal)}
              onUpdateServings={(servings) => onUpdateServings(meal.id, servings)}
              onUpdateRating={(rating) => onUpdateRating(meal.id, rating)}
            />
          </Grid>
        ))}
      </Grid>

      <Dialog open={isAddMealOpen} onClose={() => setIsAddMealOpen(false)} maxWidth="md" fullWidth>
        <DialogTitle>Maaltijd toevoegen</DialogTitle>
        <DialogContent>
          <Box sx={{ mb: 2 }}>
            <TextField
              label="Aantal personen"
              type="number"
              value={newServings}
              onChange={(e) => setNewServings(parseInt(e.target.value) || 1)}
              fullWidth
            />
          </Box>
          <List>
            {filteredMeals.map((meal) => (
              <ListItem key={meal.id} disablePadding>
                <ListItemButton onClick={() => handleAddMeal(meal)}>
                  <ListItemText
                    primary={meal.name}
                    secondary={meal.description}
                  />
                </ListItemButton>
              </ListItem>
            ))}
          </List>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setIsAddMealOpen(false)}>Sluiten</Button>
        </DialogActions>
      </Dialog>

      <Dialog open={isShoppingListOpen} onClose={() => setIsShoppingListOpen(false)} maxWidth="md" fullWidth>
        <DialogTitle>Boodschappenlijst</DialogTitle>
        <DialogContent>
          <ShoppingList
            ingredients={mealPlan.meals.flatMap(meal => 
              meal.ingredients.map(ingredient => ({
                ...ingredient,
                amount: ingredient.amount * meal.servings
              }))
            )}
            onRemoveIngredient={() => {}}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setIsShoppingListOpen(false)}>Sluiten</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default MealPlanner; 